cat > /tmp/stackalloc_nint.cs << 'EOF'
using System;

var span = (stackalloc nint[4]);
span[0] = 10;
span[1] = 20;
span[2] = 30;
span[3] = 40;

nint sum = 0;
foreach (var val in span)
    sum += val;

Console.WriteLine($"Span<nint> length: {span.Length}");
Console.WriteLine($"Sum: {sum}");
Console.WriteLine($"Element size: {nint.Size} bytes");
Console.WriteLine($"First element: {span[0]}");
EOF
